'use strict';
const mobileQuery=matchMedia('(pointer:coarse) and (max-width:1100px)');
let mobileBuffPage=0;
const mobileDeck=document.createElement('div');mobileDeck.className='touch-deck';$('touchControls').append(mobileDeck);mobileDeck.append(document.querySelector('.touch-fight'),document.querySelector('.touch-potions'));
const mobileBuffStrip=document.createElement('div');mobileBuffStrip.className='touch-buffs';mobileBuffStrip.setAttribute('aria-label','Buff มือถือ');
const mobileBuffSwitch=document.createElement('button');mobileBuffSwitch.id='mobileBuffPage';mobileBuffSwitch.onclick=()=>{mobileBuffPage=1-mobileBuffPage;updateMobileHUD()};mobileBuffStrip.append(mobileBuffSwitch);
for(let i=0;i<4;i++){const button=document.createElement('button');button.id='mobileBuff'+i;button.className='touch-buff';button.onclick=()=>{const id=supportBuffSlots()[mobileBuffPage*4+i];if(id)castSupportSkill(id)};mobileBuffStrip.append(button)}mobileDeck.append(mobileBuffStrip);
for(const [i,kind]of ['hp','mp'].entries()){const button=document.querySelector('.touch-potions').children[i];button.classList.add('touch-potion',kind+'-potion');button.setAttribute('aria-label','ใช้ยา '+kind.toUpperCase());button.innerHTML='<span class="potion-bottle"></span><small>'+kind.toUpperCase()+'</small><b></b><em></em>'}
function mobileMarkup(button,html){if(button.innerHTML!==html)button.innerHTML=html}
function updateMobileHUD(){
 const near=interactables.some(t=>Math.abs(player.x-t.x)<(t.radius||65)&&Math.abs(player.y-t.y)<48),big=document.querySelector('.touch-jump');
 big.setAttribute('aria-label',near?'โต้ตอบ':'กระโดด');big.dataset.mode=near?'interact':'jump';mobileMarkup(big.querySelector('span'),near?'<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M4 4h24v17H15l-8 7v-7H4Z" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="10" cy="12" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="22" cy="12" r="2"/></svg>':'<svg viewBox="0 0 32 32" aria-hidden="true"><path d="m8 5 9 4-2 10 11 5v4H6v-8Z" fill="currentColor"/><path d="m21 3 4-2 3 5M23 2v12" fill="none" stroke="currentColor" stroke-width="2"/></svg>');
 for(const [i,key]of ['q','w','e','r'].entries()){const button=$('touchSkill'+key.toUpperCase()),id=player.weaponLoadout[i].active[0],d=WEAPON_SKILLS[id],cd=player.cd[id]||0;button.dataset.key='Key'+key.toUpperCase();button.disabled=!weaponSkillEnabled(id)||(cd>0&&player.activeChannel?.id!==id);button.hidden=false;button.setAttribute('aria-label','Active ขั้น '+(i+1)+' · '+(d?.name||'ว่าง'));button.title=d?.name||'เลือก Active ขั้น '+(i+1);const icon=d&&typeof weaponIcon==='function'?weaponIcon(d.weapon):'<span>＋</span>';mobileMarkup(button,'<b class="touch-active-icon">'+icon+'</b><small>'+key.toUpperCase()+'</small><em>'+(cd>0?Number(cd.toFixed(1)):player.activeToggles?.[id]?'ON':'')+'</em>')}
 mobileBuffSwitch.textContent=(mobileBuffPage+1)+'/2';mobileBuffSwitch.setAttribute('aria-label','Buff หน้า '+(mobileBuffPage+1)+' จาก 2 · แตะเพื่อสลับหน้า');
 if(typeof supportBuffSlots==='function')for(let i=0;i<4;i++){const index=mobileBuffPage*4+i,id=supportBuffSlots()[index],d=WEAPON_SKILLS[id],button=$('mobileBuff'+i),cd=id?supportCooldown(id):0;button.disabled=!id||!supportSelected(id)||cd>0;button.dataset.slot=index+1;button.setAttribute('aria-label','Buff ช่อง '+(index+1)+' · '+(d?.name||'ว่าง'));button.title=d?.name||'เลือก Buff ช่อง '+(index+1);mobileMarkup(button,'<small>'+(index+1)+'</small><span>'+(d?.name||'ว่าง')+'</span><em>'+(cd>0?Math.ceil(cd):'')+'</em>')}
 for(const [i,kind]of ['hp','mp'].entries()){const button=document.querySelector('.touch-potions').children[i],id=kind+'Potion',cd=player.cd[id]||0;button.disabled=paused||!player.consumables[id]||cd>0||player[kind]>=(kind==='hp'?maxHP():maxMP());button.querySelector('b').textContent=player.consumables[id];button.querySelector('em').textContent=cd>0?Number(cd.toFixed(1)):''}
}
const joystick=$('touchJoystick');let joystickPointer=null;
function clearJoystick(){joystickPointer=null;for(const key of ['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'])keys[key]=false;joystick.querySelector('i').style.transform='translate(-50%,-50%)'}
function moveJoystick(e){if(e.pointerId!==joystickPointer)return;const r=joystick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),scale=Math.min(1,r.width*.25/Math.max(1,len));keys.ArrowLeft=dx<-14;keys.ArrowRight=dx>14;keys.ArrowUp=dy<-18;keys.ArrowDown=dy>18;joystick.querySelector('i').style.transform='translate(calc(-50% + '+dx*scale+'px),calc(-50% + '+dy*scale+'px))'}
joystick.addEventListener('pointerdown',e=>{e.preventDefault();if(paused||screen!=='play'||joystickPointer!==null)return;joystickPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);moveJoystick(e)});joystick.addEventListener('pointermove',moveJoystick);for(const type of ['pointerup','pointercancel','lostpointercapture'])joystick.addEventListener(type,e=>{if(e.pointerId===joystickPointer)clearJoystick()});
function syncMobileMode(){document.documentElement.classList.toggle('mobile-play',mobileQuery.matches);const scale=Math.min(1,Math.max(.7,(innerHeight-72)/294),Math.max(.7,(innerWidth-136)/248));mobileDeck.style.setProperty('--touch-scale',scale);keys={};touchPointers.clear();clearJoystick();document.querySelectorAll('.touch-held').forEach(button=>button.classList.remove('touch-held'))}
mobileQuery.addEventListener('change',syncMobileMode);window.addEventListener('resize',syncMobileMode);syncMobileMode();window.addEventListener('blur',()=>{clearJoystick();touchPointers.clear();document.querySelectorAll('.touch-held').forEach(button=>button.classList.remove('touch-held'))});
